    private static double parseDoubleWithStyle(String s, int style) {
        if (s == null) {
            throw new NumberFormatException("null");
        }
        String value = s;
        if ((style & NumberStyles.AllowLeadingWhite) != 0) {
            value = stripLeading(value);
        }
        if ((style & NumberStyles.AllowTrailingWhite) != 0) {
            value = stripTrailing(value);
        }
        if ((style & NumberStyles.AllowParentheses) != 0 && value.length() >= 2
                && value.charAt(0) == '(' && value.charAt(value.length() - 1) == ')') {
            value = "-" + value.substring(1, value.length() - 1);
        }
        if ((style & NumberStyles.AllowThousands) != 0) {
            value = value.replace(",", "");
        }
        return Double.parseDouble(value);
    }

    private static int parseIntWithStyle(String s, int style) {
        if ((style & NumberStyles.AllowHexSpecifier) != 0) {
            return Integer.parseUnsignedInt(normalizeIntegerLiteral(s, style), 16);
        }
        return Integer.parseInt(normalizeIntegerLiteral(s, style));
    }

    private static long parseLongWithStyle(String s, int style) {
        if ((style & NumberStyles.AllowHexSpecifier) != 0) {
            return Long.parseUnsignedLong(normalizeIntegerLiteral(s, style), 16);
        }
        return Long.parseLong(normalizeIntegerLiteral(s, style));
    }

    private static long parseUnsignedLongInRange(String s, int style, long maxValue) {
        BigInteger value = parseUnsignedBigIntegerInRange(s, style, BigInteger.valueOf(maxValue));
        return value.longValue();
    }

    private static BigInteger parseUnsignedBigIntegerInRange(String s, int style, BigInteger maxValue) {
        String normalized = normalizeIntegerLiteral(s, style);
        int radix = (style & NumberStyles.AllowHexSpecifier) != 0 ? 16 : 10;
        BigInteger value = new BigInteger(normalized, radix);
        if (value.signum() < 0 || value.compareTo(maxValue) > 0) {
            throw new NumberFormatException("Value out of range");
        }
        return value;
    }

    private static String normalizeIntegerLiteral(String s, int style) {
        if (s == null) {
            throw new NumberFormatException("null");
        }
        String value = s;
        if ((style & NumberStyles.AllowLeadingWhite) != 0) {
            value = stripLeading(value);
        }
        if ((style & NumberStyles.AllowTrailingWhite) != 0) {
            value = stripTrailing(value);
        }
        if ((style & NumberStyles.AllowThousands) != 0) {
            value = value.replace(",", "");
        }
        return value;
    }

    private static String stripLeading(String value) {
        int i = 0;
        while (i < value.length() && Character.isWhitespace(value.charAt(i))) {
            i++;
        }
        return value.substring(i);
    }

    private static String stripTrailing(String value) {
        int i = value.length() - 1;
        while (i >= 0 && Character.isWhitespace(value.charAt(i))) {
            i--;
        }
        return value.substring(0, i + 1);
    }

    @FunctionalInterface
    private interface NumberParser<T> {
        T parse();
    }

    private static <T> T parseNumber(NumberParser<T> parser) {
        try {
            return parser.parse();
        } catch (NumberFormatException ex) {
            throw new FormatException(ex.getMessage(), ex);
        }
    }

    // ---- FormatNumeric (for C# value.ToString("X2") etc.) ----

    /**
     * Formats a numeric value using a C# format specifier string (e.g. "X2", "D4", "F2").
     * This is used to convert C# {@code value.ToString("format")} calls to Java.
     *
     * @param format the C# format specifier (e.g. "X2", "x4", "D8", "F2")
     * @param value  the numeric value to format
     * @return the formatted string
     */
    public static String formatNumeric(String format, Object value) {
        return formatValue(format, value);
    }

    // ---- TryFormat helpers ----

    private static boolean writeFormattedToSpan(String formatted, Span<Character> dest, IntHolder charsWritten) {
        if (formatted.length() > dest.length()) {
            return false;
        }
        for (int i = 0; i < formatted.length(); i++) {
            dest.set(i, formatted.charAt(i));
        }
        charsWritten.value = formatted.length();
        return true;
    }

    private static String formatValue(String format, Object value) {
        if (format == null || format.isEmpty()) {
            return String.valueOf(value);
        }
        if (isCustomNumericFormat(format)) {
            return formatCustomNumeric(format, value);
        }
        Object formatArgument = toJavaFormatterArgument(value);
        String javaFormat = translateFormat(format, formatArgument);
        return String.format(Locale.ROOT, javaFormat, formatArgument);
    }

    private static boolean isCustomNumericFormat(String format) {
        for (int i = 0; i < format.length(); i++) {
            char ch = format.charAt(i);
            if (ch == '#' || ch == '0') {
                return true;
            }
        }
        return false;
    }

    private static String formatCustomNumeric(String format, Object value) {
        DecimalFormat decimalFormat = new DecimalFormat(format, DecimalFormatSymbols.getInstance(Locale.ROOT));
        decimalFormat.setGroupingUsed(format.indexOf(',') >= 0);
        decimalFormat.setRoundingMode(RoundingMode.HALF_UP);
        decimalFormat.setParseBigDecimal(true);
        String result = decimalFormat.format(toBigDecimal(value));
        if (format.startsWith("#.") && result.startsWith("0.")) {
            result = result.substring(1);
        } else if (format.startsWith("#.") && result.startsWith("-0.")) {
            result = "-" + result.substring(2);
        }
        return result;
    }

    private static BigDecimal toBigDecimal(Object value) {
        if (value instanceof Decimal decimal) {
            return decimal.toBigDecimal();
        }
        if (value instanceof BigDecimal bigDecimal) {
            return bigDecimal;
        }
        if (value instanceof BigInteger bigInteger) {
            return new BigDecimal(bigInteger);
        }
        if (value instanceof Byte || value instanceof Short || value instanceof Integer || value instanceof Long) {
            return BigDecimal.valueOf(((Number) value).longValue());
        }
        if (value instanceof Float || value instanceof Double) {
            return BigDecimal.valueOf(((Number) value).doubleValue());
        }
        if (value instanceof Number number) {
            return BigDecimal.valueOf(number.doubleValue());
        }
        return new BigDecimal(String.valueOf(value));
    }

    private static Object toJavaFormatterArgument(Object value) {
        if (value instanceof Decimal decimal) {
            return decimal.toBigDecimal();
        }
        return value;
    }

    private static String translateFormat(String format, Object value) {
        char specChar = format.charAt(0);
        char spec = Character.toUpperCase(specChar);
        String arg = format.substring(1);
        switch (spec) {
            case 'X': {
                int width = arg.isEmpty() ? 0 : Integer.parseInt(arg);
                // Preserve case: C# "X" → uppercase hex, C# "x" → lowercase hex
                String caseChar = Character.isUpperCase(specChar) ? "X" : "x";
                String f = "%" + (width > 0 ? "0" + width : "") + caseChar;
                return f;
            }
            case 'F': {
                int precision = arg.isEmpty() ? 2 : Integer.parseInt(arg);
                return "%" + "." + precision + "f";
            }
            case 'D': {
                int width = arg.isEmpty() ? 0 : Integer.parseInt(arg);
                return "%" + (width > 0 ? "0" + width + "d" : "d");
            }
            case 'N': {
                int precision = arg.isEmpty() ? 2 : Integer.parseInt(arg);
                return "%" + "." + precision + "f";
            }
            case 'E': {
                int precision = arg.isEmpty() ? 6 : Integer.parseInt(arg);
                // Preserve case: C# "E" → uppercase, C# "e" → lowercase
                String eChar = Character.isUpperCase(specChar) ? "E" : "e";
                return "%" + "." + precision + eChar;
            }
            case 'G': {
                int precision = arg.isEmpty() ? 0 : Integer.parseInt(arg);
                if (value instanceof Float || value instanceof Double) {
                    return precision > 0 ? "%" + "." + precision + "g" : "%g";
                }
                return precision > 0 ? "%" + "." + precision + "f" : "%f";
            }
            default:
                return "%" + format;
        }
    }

